"""Governance for the agents (generated by G2C for E2A v1.2): ordered stages run for every
agent (screening before it reads, approval after), and each agent's tool allow-list."""
from e2a import BaseGovernanceFramework, ApprovalStage, CapacityStage, FirewallStage, InflightLimiter, RedactionStage, TokenBudgetStage


class ServiceGovernance(BaseGovernanceFramework):
    tool_policy = {
        "IntentAgent": [],
        "EvidenceAgent": [
            "get_reconciliation_exception",
            "get_settlement",
            "get_settlement_events",
            "get_order",
            "get_audit_findings"
        ],
        "InvestigatorAgent": [],
        "ProposalAgent": [],
        "ExecutionAgent": [
            "get_settlement",
            "post_adjustment"
        ]
    }

    def __init__(self) -> None:
        self.stages = [
        CapacityStage(InflightLimiter(20)),
        TokenBudgetStage(),
        FirewallStage(injection_patterns=[r"ignore (all )?(previous|prior) instructions"]),  # TODO: your patterns
        ApprovalStage(required=lambda state, ctx: False),  # TODO: when a human must approve
        RedactionStage(),  # TODO: your redaction rules (compile_redactions)
        ]
